    if (!result.success) {
      const firstIssue = result.error.issues[0];
      // 1. return custom error message if the failed rule had any specified
      // 2. if not return "global error" if specified
      // 3. otherwise return the zod-error

      /* no way to detect if the ZodError.message is zod default or not, unfortunally ZodError has no flag to check that */
